css:
.btn-gradient-cosmic {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: #fff;
  box-shadow: 0 4px 20px rgba(102, 126, 234, 0.35);
}

.btn-gradient-cosmic:hover {
  transform: translateY(-4px) scale(1.05);
  box-shadow: 0 10px 40px rgba(102, 126, 234, 0.5);
}

.btn-gradient-cosmic:hover i {
  animation: spin 1s linear infinite;
}

.btn-border-pink-glow {
  border: 2px solid #f093fb;
  background: transparent;
  color: #f093fb;
}

.btn-border-pink-glow:hover {
  background: #f093fb;
  color: #0a0a1a;
  box-shadow: 0 0 30px rgba(240, 147, 251, 0.3);
  transform: scale(1.05);
}

.btn-border-pink-glow:hover i {
  animation: bounce 0.6s ease;
}

.btn-3d-dark-cube {
  background: #2d3436;
  color: #dfe6e9;
  box-shadow: 0 4px 0 #1a1a1a, 0 8px 20px rgba(0, 0, 0, 0.4);
  border-radius: 12px;
}

.btn-3d-dark-cube:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 0 #1a1a1a, 0 12px 30px rgba(0, 0, 0, 0.5);
}

.btn-3d-dark-cube:active {
  transform: translateY(4px);
  box-shadow: 0 2px 0 #1a1a1a;
}

.btn-gradient-gold-crown {
  background: linear-gradient(135deg, #f7971e, #ffd200);
  color: #1a1a2e;
}

.btn-gradient-gold-crown::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(255, 255, 255, 0.2);
  transform: translateX(-100%);
  transition: transform 0.4s;
}

.btn-gradient-gold-crown:hover::after {
  transform: translateX(0);
}

.btn-gradient-gold-crown:hover {
  transform: scale(1.05);
  box-shadow: 0 8px 30px rgba(247, 151, 30, 0.4);
}

.btn-gradient-gold-crown span,
        .btn-gradient-gold-crown i {
  position: relative;
  z-index: 1;
}

.btn-glassmorphism-clean {
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.03);
  backdrop-filter: blur(12px);
  color: rgba(255, 255, 255, 0.85);
}

.btn-glassmorphism-clean:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.25);
  transform: translateY(-3px) scale(1.03);
  box-shadow: 0 15px 40px rgba(0, 0, 0, 0.3);
}

.btn-3d-crimson-depth {
  background: #e74c3c;
  color: #fff;
  box-shadow: 0 6px 0 #c0392b, 0 10px 25px rgba(231, 76, 60, 0.3);
  border-radius: 12px;
}

.btn-3d-crimson-depth:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 0 #c0392b, 0 15px 35px rgba(231, 76, 60, 0.4);
}

.btn-3d-crimson-depth:active {
  transform: translateY(4px);
  box-shadow: 0 2px 0 #c0392b;
}

.btn-border-neon-flow {
  border: 2px solid transparent;
  background: transparent;
  color: #48dbfb;
}

.btn-border-neon-flow::before {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 50px;
  padding: 2px;
  background: linear-gradient(135deg, #48dbfb, #ff9ff3);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
}

.btn-border-neon-flow:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(72, 219, 251, 0.2);
}

.btn-anim-sync-loader {
  background: #00b894;
  color: #fff;
}

.btn-anim-sync-loader:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(0, 184, 148, 0.4);
}

.btn-anim-sync-loader:hover i {
  animation: spin 1s linear infinite;
}

.btn-anim-heart-pulse {
  background: rgba(255, 107, 107, 0.12);
  color: #ff6b6b;
}

.btn-anim-heart-pulse:hover {
  background: rgba(255, 107, 107, 0.2);
  transform: translateY(-3px);
}

.btn-anim-heart-pulse:hover i {
  animation: heartBeat 0.6s ease-in-out;
}

.btn-anim-water-ripple {
  background: #6c5ce7;
  color: #fff;
  border-radius: 12px;
}

.btn-anim-water-ripple::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(255, 255, 255, 0.15);
  transform: scale(0);
  border-radius: 50%;
  transition: transform 0.6s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.btn-anim-water-ripple:hover::after {
  transform: scale(3);
}

.btn-anim-water-ripple:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(108, 92, 231, 0.4);
}

.btn-anim-water-ripple span,
        .btn-anim-water-ripple i {
  position: relative;
  z-index: 1;
}

.btn-cart-shopping-glow {
  background: linear-gradient(135deg, #ff6b6b, #ee5a24);
  color: #fff;
}

.btn-cart-shopping-glow:hover {
  transform: translateY(-4px) scale(1.05);
  box-shadow: 0 8px 30px rgba(255, 107, 107, 0.4);
}

.btn-cart-shopping-glow:hover i {
  transform: translateX(-6px) rotate(-10deg);
}

.btn-search-cyan-glow {
  border: 2px solid #48dbfb;
  background: transparent;
  color: #48dbfb;
}

.btn-search-cyan-glow:hover {
  background: #48dbfb;
  color: #0a0a1a;
  box-shadow: 0 0 30px rgba(72, 219, 251, 0.3);
  transform: translateY(-3px);
}

.btn-search-cyan-glow:hover i {
  transform: scale(1.2);
}

.btn-settings-gear-spin {
  background: rgba(108, 92, 231, 0.12);
  color: #a29bfe;
}

.btn-settings-gear-spin:hover {
  background: rgba(108, 92, 231, 0.2);
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(108, 92, 231, 0.2);
}

.btn-settings-gear-spin:hover i {
  transform: rotate(180deg);
}

.btn-notification-bell-ring {
  background: rgba(254, 202, 87, 0.12);
  color: #feca57;
  position: relative;
  overflow: visible;
}

.btn-notification-bell-ring::before {
  content: '5';
  position: absolute;
  top: -6px;
  right: -6px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #ff6b6b;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden !important;
}

.btn-notification-bell-ring:hover {
  background: rgba(254, 202, 87, 0.2);
  transform: translateY(-3px);
}

.btn-notification-bell-ring:hover i {
  animation: ringBell 0.6s ease-in-out;
}

.btn-like-pulse-bounce {
  background: rgba(255, 159, 243, 0.12);
  color: #ff9ff3;
}

.btn-like-pulse-bounce:hover {
  background: rgba(255, 159, 243, 0.2);
  transform: translateY(-3px);
}

.btn-like-pulse-bounce:hover i {
  animation: likePulse 0.6s ease-in-out;
}

.btn-share-teal-glow {
  background: rgba(0, 206, 201, 0.12);
  color: #00cec9;
}

.btn-share-teal-glow:hover {
  background: rgba(0, 206, 201, 0.2);
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(0, 206, 201, 0.2);
}

.btn-share-teal-glow:hover i {
  transform: translateY(-4px);
}

.btn-download-bounce-mint {
  border: 2px solid #55efc4;
  background: transparent;
  color: #55efc4;
}

.btn-download-bounce-mint:hover {
  background: #55efc4;
  color: #0a0a1a;
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(85, 239, 196, 0.3);
}

.btn-download-bounce-mint:hover i {
  animation: downloadBounce 0.6s ease-in-out;
}

.btn-delete-coral-danger {
  background: rgba(255, 107, 107, 0.12);
  color: #ff6b6b;
}

.btn-delete-coral-danger:hover {
  background: rgba(255, 107, 107, 0.2);
  transform: translateY(-3px);
}

.btn-delete-coral-danger:hover i {
  transform: scale(0.8) rotate(10deg);
}

.btn-security-lock-purple {
  border: 2px solid #a29bfe;
  background: transparent;
  color: #a29bfe;
}

.btn-security-lock-purple:hover {
  background: #a29bfe;
  color: #0a0a1a;
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(162, 155, 254, 0.3);
}

.btn-security-lock-purple:hover i {
  transform: scale(0.8);
}

.btn-security-unlock-cyan {
  background: rgba(72, 219, 251, 0.12);
  color: #48dbfb;
}

.btn-security-unlock-cyan:hover {
  background: rgba(72, 219, 251, 0.2);
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(72, 219, 251, 0.2);
}

.btn-security-unlock-cyan:hover i {
  transform: translateX(4px);
}

.btn-star-premium-spin {
  background: linear-gradient(135deg, #feca57, #f39c12);
  color: #0a0a1a;
}

.btn-star-premium-spin:hover {
  transform: translateY(-4px) scale(1.05);
  box-shadow: 0 8px 30px rgba(254, 202, 87, 0.4);
}

.btn-star-premium-spin:hover i {
  animation: spin 1s linear infinite;
}

.btn-gradient-vibrant-leaf {
  background: linear-gradient(135deg, #a8e063, #56ab2f);
  color: #fff;
  box-shadow: 0 4px 20px rgba(86, 171, 47, 0.35);
}

.btn-gradient-vibrant-leaf:hover {
  transform: translateY(-4px) scale(1.05);
  box-shadow: 0 10px 35px rgba(86, 171, 47, 0.5);
}

.btn-gradient-rose-fire {
  background: linear-gradient(135deg, #f093fb, #f5576c);
  color: #fff;
  box-shadow: 0 4px 20px rgba(245, 87, 108, 0.35);
  border-radius: 12px;
}

.btn-gradient-rose-fire:hover {
  transform: translateY(-4px) scale(1.05);
  box-shadow: 0 10px 35px rgba(245, 87, 108, 0.5);
}

.btn-gradient-rose-fire:hover i {
  animation: spin 2s linear infinite;
}

.btn-slide-blue-cloud {
  border: 2px solid #4facfe;
  background: transparent;
  color: #4facfe;
  border-radius: 12px;
}

.btn-slide-blue-cloud::before {
  content: '';
  position: absolute;
  inset: 0;
  background: #4facfe;
  transform: scaleX(0);
  transition: transform 0.4s;
  display: flex;
  align-items: center;
  justify-content: center;
  padding-right: 30px;
  transform-origin: right;
}

.btn-slide-blue-cloud:hover::before {
  transform: scaleX(1);
  transform-origin: left;
}

.btn-slide-blue-cloud:hover {
  color: #0a0a1a;
  box-shadow: 0 0 30px rgba(79, 172, 254, 0.3);
}

.btn-slide-blue-cloud span,
        .btn-slide-blue-cloud i {
  position: relative;
  z-index: 1;
}

.btn-gradient-fresh-mint {
  background: linear-gradient(135deg, #43e97b, #38f9d7);
  color: #0a0a1a;
}

.btn-gradient-fresh-mint:hover {
  transform: translateY(-4px) scale(1.05);
  box-shadow: 0 8px 30px rgba(67, 233, 123, 0.4);
}

.btn-3d-midnight-slate {
  background: #2c3e50;
  color: #ecf0f1;
  box-shadow: 0 4px 0 #1a252f;
  border-radius: 12px;
}

.btn-3d-midnight-slate:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 0 #1a252f;
}

.btn-3d-midnight-slate:active {
  transform: translateY(4px);
  box-shadow: 0 2px 0 #1a252f;
}

.btn-gradient-gem-sparkle {
  background: linear-gradient(135deg, #fa709a, #fee140);
  color: #1a1a2e;
}

.btn-gradient-gem-sparkle::after {
  content: '✨';
  position: absolute;
  right: -20px;
  top: -20px;
  font-size: 30px;
  opacity: 0.3;
  transition: all 0.4s;
}

.btn-gradient-gem-sparkle:hover::after {
  right: 10px;
  top: 10px;
  opacity: 1;
}

.btn-gradient-gem-sparkle:hover {
  transform: translateY(-4px) scale(1.05);
  box-shadow: 0 8px 30px rgba(250, 112, 154, 0.4);
}

.btn-gradient-gem-sparkle:hover i {
  animation: spin 3s linear infinite;
}

.btn-neon-pulse-pink {
  border: 2px solid #fd79a8;
  background: transparent;
  color: #fd79a8;
}

.btn-neon-pulse-pink:hover {
  background: #fd79a8;
  color: #0a0a1a;
  transform: translateY(-3px);
  box-shadow: 0 8px 30px rgba(253, 121, 168, 0.3);
}

.btn-dark-crimson-fire {
  background: #1a1a2e;
  color: #e94560;
