}

.btn-gradient-night-sky {
  background: linear-gradient(135deg, #0f0c29, #302b63, #24243e);
  color: #fff;
  box-shadow: 0 4px 20px rgba(48, 43, 99, 0.4);
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.btn-gradient-night-sky:hover {
  transform: translateY(-4px) scale(1.05);
  box-shadow: 0 10px 40px rgba(48, 43, 99, 0.6);
}

.btn-gradient-night-sky:hover i {
