}

.btn-social-reddit-fa:hover {
  transform: translateY(-4px) scale(1.05);
  box-shadow: 0 8px 30px rgba(255, 69, 0, 0.4);
}

.btn-social-reddit-fa:hover i {
  animation: spin 2s linear infinite;
}

